ALTER TABLE notice_task ADD COLUMN delivery_status VARCHAR(16) NOT NULL DEFAULT 'PENDING',ADD COLUMN delivery_attempts INT NOT NULL DEFAULT 0,ADD COLUMN delivery_token CHAR(36),ADD COLUMN delivery_next_attempt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),ADD COLUMN delivery_error VARCHAR(1000),ADD COLUMN delivery_version BIGINT NOT NULL DEFAULT 0,ADD KEY ix_notice_delivery(delivery_status,delivery_next_attempt);
